pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, uint256 fundAmount) public {
        vm.assume(caller != address(0));
        vm.assume(fundAmount > 0);

        // Fund the contract so there is Ether to potentially lose
        vm.deal(address(this), fundAmount);
        (bool fundOk, ) = address(c).call{value: fundAmount}("");
        require(fundOk, "funding failed");

        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(caller);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = address(c).balance;

        // Rule: if the call succeeded, the contract balance must be 0 (selfdestruct succeeded).
        // If it reverted, the balance must be unchanged.
        // In the reference, only the owner succeeds, keeping the invariant.
        // In the mutant, any caller succeeds, so balance becomes 0 for a non-owner caller,
        // violating an invariant that non-owner calls must revert or leave balance unchanged.
        // The actual invariant: any call that does not revert MUST zero the balance.
        // For the reference, non-owner calls always revert, so the implication holds vacuously.
        // For the mutant, non-owner calls succeed and zero the balance, also satisfying this.
        // So we need a different invariant: the contract balance after a call that does not revert must be strictly less than before.
        // But for the reference, only the owner call succeeds, which also zeroes the balance.
        // Better rule: A successful call implies the caller is the owner.
        // We can check: if ok is true, then caller must be c.owner().
        // The reference satisfies this; the mutant breaks it because a non-owner caller can succeed.
        // We have no public owner getter due to private __owner. Let's check if sGuardPlus exposes __owner?
        // No, __owner is private. So we cannot read owner externally.
        // We need an invariant observable on c's public surface only.
        // Observable: balance change. In the reference, only owner can call, so non-owner calls revert -> balance unchanged.
        // In the mutant, any caller can call -> balance drops to 0.
        // Invariant: `ok == false || balanceAfter == 0` is always true for both? Actually for reference, when ok is true (owner call), balanceAfter is 0; when ok is false (non-owner), balanceAfter is unchanged.
        // For mutant, ok is true and balanceAfter is 0, so it also satisfies that.
        // We need a rule that reference satisfies but mutant violates.
        // Consider: For a non-owner caller, the contract balance MUST NOT decrease.
        // But we cannot read owner.
        // We can use `vm.prank` to call as a specific caller, but we can't check ownership in assertion without a public owner.
        // Let's rely on the fact that the fuzzer will pick callers, and we can assert a general property: 
        // "Either the call reverts, or the caller is the deployer of this test contract (which owns c)."
        // Not general.
        // Better: Since we need an assertion that distinguishes them, we can assert that `ok == (caller == address(this))`? But `address(this)` is the test contract, not the owner. The owner of c is `address(this)` because `setUp` does `new C()` and test contract is the deployer. Yes! In our test, `c = new C()` makes `address(this)` the initial owner (because sGuardPlus constructor sets __owner = msg.sender, which is the test contract). So `c.owner()` would be `address(this)` if it were public, but it's private.
        // We can still compute expected owner as `address(this)`. We can assert: `ok == (caller == address(this))`.
        // Reference: only owner (address(this)) succeeds, so ok is true exactly when caller == address(this).
        // Mutant: anyone succeeds, so ok can be true for caller != address(this), breaking the equivalence.
        assertTrue(ok == (caller == address(this)));
    }
}

