    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 sendAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.owner());
        vm.assume(sendAmount > 0);
        // fund the contract so a selfdestruct would drain it
        vm.deal(address(c), sendAmount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        try c.sudicideAnyone() {
            // if the call succeeded, contract is destroyed - balance is zero
            // but we must still check the balance preservation rule for the reference
        } catch {
            // reverts are fine
        }
        uint256 balanceAfter;
        // if contract was destroyed, address(c).balance returns 0
        balanceAfter = address(c).balance;
