pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        // Record the owner before the call by reading the public auto-generated getter.
        // Since __owner is private and not exposed, we approximate owner identity by asserting
        // that the contract still exists (code size > 0) and its supposed owner (msg.sender in constructor)
        // does not change. However, the contract has no owner() getter; we use the selfdestruct
        // effect: after selfdestruct, all storage is cleared. We can detect this via a low-level
        // call to a public view/pure function or checking code size. The contract has no public
        // getters besides inherited ones. The only exposed behavior is sudicideAnyone().
        // We will check that after the call, the code size of c is unchanged (non-zero) OR
        // the contract is now empty (code size 0). In the reference, only the owner (this contract
        // or the deployer) can call sudicideAnyone(), which selfdestructs and removes code.
        // In the bug, anyone can call it and remove code.
        // To make the test pass for reference and fail for bug, we need a property that holds
        // universally for reference but is broken by the bug.
        // Property: For any caller that is NOT the owner, the call to sudicideAnyone() MUST revert.
        // In the reference, only owner can call successfully; the bug allows any caller.
        // However, the owner is not exposed as a getter. We only know the constructor sets __owner = msg.sender during deploy in setUp().
        // We can read the owner through the auto-generated getter if it were public, but it's private.
        // The contract sGuardPlus has __owner private, no getter. We cannot query it.
        // Alternative: We can compare behavior based on call success/failure.
        // Since we cannot read the owner, we must make the fuzzer provide addresses that may or may not be the owner.
        // The deployer in setUp is address(this) for InvMutTest. The constructor of C sets __owner = msg.sender, which is address(this) during setUp().
        // Thus, the owner is address(this). We can vm.assume(caller != address(this)) to restrict to non-owners.
        // Then call sudicideAnyone as caller and check it reverts (reference) vs succeeds (bug).
        bool success;
        vm.prank(caller);
        try c.sudicideAnyone() { success = true; } catch { success = false; }
        // For any caller != owner, reference reverts (success == false), bug succeeds (success == true).
        assertTrue(success == false);
    }
}

