pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // The reference only allows the original owner (deployer, i.e. this test contract) to selfdestruct.
        // Any other actor should not be able to trigger it, so the code should remain intact.
        bool ok;
        vm.prank(actor);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        // For a non-owner (any fuzzed actor != deployer), reference reverts (ok=false).
        // If it succeeds (ok=true), code must be empty (selfdestruct executed).
        // In reference, ok is false for non-owner, so the assertion holds (false => true).
        // In mutant, ok is true and code is empty, so the assertion holds (true => code size == 0).
        // But the mutant allows the call to succeed when actor is not owner, which changes the state (code size becomes 0) whereas reference would prevent it.
        // This assertion checks: if the call succeeded, code size must be 0.
        // For reference with a non-owner actor, the call always fails (ok=false), so the implication is vacuously true.
        // For mutant with a non-owner actor, the call succeeds and selfdestruct runs, making code size 0 => assertion true.
        // Wait, we need a property that reference ALWAYS satisfies and mutant SOMETIMES violates.
        // The property: For any caller, it is NOT the case that the call succeeds AND afterwards the code size is NOT empty.
        // That is: !(ok && code.length > 0)
        // Reference: For non-owner, ok=false, so !(false && ...) = true. For owner, ok=true and code.length would become 0 after selfdestruct, but we can't test owner in this fuzz because actor is only non-owner. The reference will never have ok=true && code.length>0.
        // Mutant: For non-owner, ok=true, but selfdestruct runs, code.length becomes 0, so still !(true && false) = true. This still holds.
        // The difference is: in reference, non-owner call reverts and code stays non-empty; in mutant, non-owner call succeeds and code becomes empty. So "code size becomes 0" is the observable effect.
        // Let's assert: If actor is not the deployer (owner), then code size must be > 0 after the attempt (because the selfdestruct should not have happened).
        // But the fuzzer provides actor, and we don't know the owner inside the test without a getter.
        // However, we can derive the owner: the deployer of C is this test contract (since setUp does new C()). So owner = address(this).
        // Since we assume actor != address(this), actor is a non-owner.
        // Then we assert: code size > 0.
        // Reference: revert -> code size still > 0 -> assert true.
        // Mutant: selfdestruct succeeded -> code size == 0 -> assert false -> FAILS. Good!
        assertTrue(actor != address(this) ? address(c).code.length > 0 : true);
    }
}

